','0030a653-904b-487c-a5c8-18439e92fd2d','5f75f226-dba1-4457-8f92-f8a5761fba20','2e903aab-d02f-456d-8371-a25685dcf29c','4dfedcfa-c913-4d77-a8ce-5be1b4b34b42','916985b1-1eb9-490c-b07c-37bfc01982f0','6791ed61-a561-4c89-955d-a96e2ecb24b7','4ea4c8e8-f809-4403-9ac9-45feb3af70d8','57429e5f-b60d-41bf-aab3-452830bccaea','650b36f5-185d-4449-a46c-4be44423f074','47444030-fbc9-4427-83ff-a01bd7174257','60fd01b6-891d-497f-9f81-065b040bca3a','d4837927-5a98-46f5-88a6-519baedd4f96','0de4ec8a-2bf6-4960-bc16-6dfaf5100b4a','874e364f-793e-477c-ad0b-9358f439fa3c','24a37251-a2db-4ddb-a6ad-5bac4112a8ef','0ef0b6cd-ff46-46cf-b098-6a48a76dd821','14ec2029-fae9-4fc9-bea0-7ad2d812b3dc','719a50df-3aca-46d8-8f9b-d70df4669896','c45d300e-d9b9-4013-9c81-04a682f12b31','1505c7f6-5c36-40b6-85b7-45eabb077534','3d801b11-df69-4885-b58c-601557d2500e','ec218044-fa22-45a3-9371-7fce48c108e8','1dd34081-fec3-4055-859a-501de5407187','0838c753-d383-48c5-a22f-aab1672eae4f','07ef9bbb-739d-4807-9928-ef02b7d7583f','efc05957-06a3-4b0e-8097-9926841fdaff','22c1824d-b601-4050-83ae-edb18b8e98bb','9c9ba44a-5dd0-4d74-8e92-a61791710194','75042cc3-3d10-45ee-ba37-fc37d552f32a','610f6069-076d-496c-af58-0ee910308b30','f99d019c-6b73-4f89-bd9e-9dc731e6b5f3','76ca33ec-f07a-4bf6-83f6-d45bd2fb4c7b','b2f2de47-2c10-4b83-bf97-89cdfd695e18','90fdfeba-dc7f-464c-9420-06a78ddb1830','f112c2b6-7101-4fb9-bee4-94d2c90ef8c4')
), bodies as (
  select v.*, vr.image_needed, vr.image_approval,
    coalesce((select jsonb_agg(jsonb_build_object(
      'key', c.choice_key, 'text', c.choice_text) order by c.choice_key)
      from app.mcq_choices c where c.content_item_version_id = v.content_item_version_id),
      '[]'::jsonb) as choices,
    coalesce((select jsonb_agg(jsonb_build_object(
      'key', coalesce(p.part->>'part_key',p.part->>'part_id',p.ordinality::text),
      'text', coalesce(nullif(p.part->>'prompt',''),p.part->>'prompt_text')) order by p.ordinality)
      from jsonb_array_elements(case
        when jsonb_typeof(v.prompt_json->'parts')='array' then v.prompt_json->'parts'
        when jsonb_typeof(v.item_package_payload->'parts')='array' then v.item_package_payload->'parts'
        else '[]'::jsonb end) with ordinality as p(part,ordinality)
      where jsonb_typeof(p.part)='object' and
        (jsonb_typeof(p.part->'prompt')='string' or jsonb_typeof(p.part->'prompt_text')='string')
        and nullif(btrim(coalesce(nullif(p.part->>'prompt',''),p.part->>'prompt_text')),'') is not null),
      '[]'::jsonb) as part_prompts,
    coalesce((select jsonb_agg(jsonb_build_object(
      'bucket', a.storage_bucket, 'path', a.storage_path,
      'alt', a.alt_text, 'long_description', a.long_description,
      'approved', a.approved_at is not null,
      'object_present', exists (select 1 from storage.objects o
        where o.bucket_id = a.storage_bucket and o.name = a.storage_path))
      order by a.storage_bucket,a.storage_path)
      from app.content_asset_metadata a
      where a.content_item_version_id = v.content_item_version_id), '[]'::jsonb) as assets,
    coalesce((select jsonb_agg(jsonb_build_object(
      'figure_id', u.figure_id, 'role', u.role, 'status', f.status, 'family', f.family)
      order by u.figure_id,u.role)
      from app.figure_uses u join app.figures f on f.figure_id = u.figure_id
      where u.question_version_id = v.content_item_version_id), '[]'::jsonb) as question_figures
  from versions v left join app.content_visual_requirements vr
    on vr.content_item_version_id = v.content_item_version_id
), marked as (
  select b.*, concat_ws(' ',stem,stimulus,choices::text,part_prompts::text) as visible_text
  from bodies b
)
select (select coalesce(jsonb_agg(jsonb_build_object('unit',r.unit_number,'topic',r.topic_code,'title',r.topic_title,'assignment',r.assignment_status)), '[]'::jsonb) from app.content_item_topic_resolution r where r.content_item_version_id=marked.content_item_version_id) as topic_evidence,
 (select coalesce(jsonb_agg(jsonb_build_object('units',l.required_units,'status',l.label_status,'topics',l.assessed_topics,'source',l.source,'validated_version',l.validated_against_version_id,'hash_matches',l.validated_against_taxo_hash=app.taxonomy_relevant_hash(marked.content_item_version_id))), '[]'::jsonb) from app.content_taxonomy_labels l where l.content_item_id=marked.content_item_id and l.label_scope='serving' and l.superseded_by is null) as serving_labels,
 prompt_json->'modules' as authored_modules,prompt_json->'subtopics' as authored_subtopics,
 subject_key,subject_name,content_key,content_item_id,content_item_version_id,
  version_num,item_type,practice_format,exam_pack_version_id,pack_status,
  pack_retired_at,is_latest_version,teaching_designated,
  stem,stimulus,choices,part_prompts,
  -- Only presentation subtrees: prompt/package objects can contain answer keys.
  prompt_json->'stimuli' as legacy_stimuli,
  prompt_json->'stimulus_table' as legacy_stimulus_table,
  item_package_payload->'stimuli' as package_stimuli,
  stimulus_image_path,image_needed,image_approval,assets,question_figures,
  case when nullif(btrim(stimulus_image_path),'') is null then null else
    exists (select 1 from storage.objects o where o.bucket_id='content-assets'
      and o.name=marked.stimulus_image_path) end as path_object_present,
  visible_text ~* '\m(figure|image|diagram|graph|chart|plot|scatterplot|histogram|boxplot|dotplot|pedigree|phylogenetic|circuit|spectrum|micrograph|table|map)\M'
    as visual_language_signal,
  visible_text ~* '(shown|pictured|illustrated|depicted) (above|below)|following (graph|diagram|figure)|the (figure|diagram|graph) (shows|depicts)'
    as explicit_reference_signal,
  visible_text ~* '\m(draw|sketch|construct|create|plot)\M.{0,60}\m(graph|diagram|curve|histogram|scatterplot|boxplot|dotplot)\M'
    as construction_signal,
  md5(jsonb_build_object('stem',stem,'stimulus',stimulus,'choices',choices,
    'parts',part_prompts,'prompt',prompt_json,'package',item_package_payload,
    'image_path',stimulus_image_path)::text) as audit_content_digest
from marked order by subject_name,content_key,version_num;
